from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _dependency_solver(data, name_order, preference):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    best = None
    best_key = None

    def visit(installed, edges):
        nonlocal best, best_key
        # Resolve all currently required names by branching over their versions.
        unresolved = [name for name in installed if name not in installed]
        # The mapping holds each chosen version; requirements are accumulated separately.

    requirements = {}

    def search(chosen, reqs, graph):
        nonlocal best, best_key
        pending = [name for name in reqs if name not in chosen]
        if pending:
            name = min(pending)
            low, high = reqs[name]
            rows = [row for row in packages[name]
                    if low <= row["version"] <= high
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            rows.sort(key=lambda r: r["version"], reverse=(preference == "maximum"))
            for row in rows:
                v = row["version"]
                deps = [d for d in row.get("deps", [])
                        if not d.get("feature") or d.get("feature") in features]
                nreq = {k: tuple(vv) for k, vv in reqs.items()}
                ngraph = {k: list(vv) for k, vv in graph.items()}
                nreq[name] = (low, high)
                ngraph[name] = []
                valid = True
                for d in deps:
                    dn = d["name"]
                    ngraph[name].append(dn)
                    bounds = (d["min"], d["max"])
                    if dn in nreq:
                        lo, hi = nreq[dn]
                        bounds = (max(lo, bounds[0]), min(hi, bounds[1]))
                        if bounds[0] > bounds[1]:
                            valid = False
                            break
                    nreq[dn] = bounds
                    if dn in chosen and not bounds[0] <= chosen[dn] <= bounds[1]:
                        valid = False
                        break
                if not valid:
                    continue
                nchosen = dict(chosen)
                nchosen[name] = v
                search(nchosen, nreq, ngraph)
            return

        # Complete assignment: validate all dependency constraints and acyclicity.
        for src, dests in graph.items():
            if any(dst not in chosen for dst in dests):
                return
        state, finished = set(), set()

        def acyclic(node):
            if node in state:
                return False
            if node in finished:
                return True
            state.add(node)
            if any(not acyclic(dst) for dst in graph.get(node, [])):
                return False
            state.remove(node)
            finished.add(node)
            return True

        if not all(acyclic(n) for n in chosen):
            return
        vector = tuple(chosen.get(n, -1) for n in names)
        key = vector if preference == "maximum" else tuple(-x for x in vector)
        if best_key is None or key > best_key:
            best_key, best = key, dict(chosen)

    initial = {name: tuple(bounds) for name, bounds in roots.items()}
    search({}, initial, {})
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _build_dependency(name_order, preference):
    return lambda data: _dependency_solver(data, name_order, preference)


def _build_component_06():
    def rounded(n, d, mode):
        if mode == "half_up":
            return (2 * n + d) // (2 * d)
        return n // d

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            eid = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if eid not in winners or key > winners[eid][0]:
                winners[eid] = (key, event)
        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        options = [j for j in jobs if j["id"] not in blocked]
        best_ids = None
        best_value = None

        def valid(subset, final=False):
            ids = {j["id"] for j in subset}
            if not mandatory.issubset(ids):
                return False
            counts = {}
            for j in subset:
                counts[j["group"]] = counts.get(j["group"], 0) + 1
            if any(counts.get(g, 0) > hi for g, (lo, hi) in quotas.items()):
                return False
            if final and any(counts.get(g, 0) < lo for g, (lo, hi) in quotas.items()):
                return False
            ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
            for i, job in enumerate(ordered):
                overlaps = sum(other["start"] < job["end"] and job["start"] < other["end"]
                               for other in ordered)
                if overlaps > 2:
                    return False
            return True

        def enumerate_subsets(pos, subset):
            nonlocal best_ids, best_value
            if len(subset) == k:
                if not valid(subset, True):
                    return
                ids = tuple(sorted(j["id"] for j in subset))
                value = sum(j["value"] for j in subset)
                if best_value is None or value > best_value or (value == best_value and ids < best_ids):
                    best_value, best_ids = value, ids
                return
            if pos == len(options) or len(subset) + len(options) - pos < k:
                return
            job = options[pos]
            if valid(subset + [job]):
                enumerate_subsets(pos + 1, subset + [job])
            enumerate_subsets(pos + 1, subset)

        if len(mandatory) > k or mandatory & blocked:
            return {"error": "impossible"}
        enumerate_subsets(0, [])
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        indexes = {node: i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = 1 << indexes[data["source"]] if data["source"] in indexes else 0
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        start_state = (data["source"], initial_mask, data["coupons"])
        dist = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
        while queue:
            time, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if time != dist.get(state):
                continue
            if node == data["target"] and mask == full and time <= data["deadline"]:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], coupons)]
                if coupons:
                    choices.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
                for duration, remaining in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    newmask = mask | (1 << indexes[nxt] if nxt in indexes else 0)
                    ns = (nxt, newmask, remaining)
                    if arrival < dist.get(ns, float("inf")):
                        dist[ns] = arrival
                        heapq.heappush(queue, (arrival, nxt, newmask, remaining))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_dependency("ascending", "maximum"),
    "component_02": _build_dependency("ascending", "minimum"),
    "component_03": _build_dependency("descending", "maximum"),
    "component_04": _build_dependency("descending", "minimum"),
    "component_05": _build_dependency("ascending", "maximum"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}

